export type TransactionStatus = 'paid' | 'pending' | 'refunded' | 'failed'

export type Transaction = {
  id: string
  customer: string
  email: string
  amount: number
  status: TransactionStatus
  createdAt: string
}

export type Page = {
  rows: Transaction[]
  /** Offset of the next page, or null once the last page has been served */
  nextCursor: number | null
}

export const TOTAL = 240
export const PAGE_SIZE = 25

const FIRST = ['Ava', 'Liam', 'Noor', 'Mateo', 'Yuki', 'Sofia', 'Omar', 'Ines']
const LAST = ['Rivera', 'Chen', 'Haddad', 'Novak', 'Okafor', 'Silva', 'Berg']
const STATUSES: TransactionStatus[] = [
  'paid',
  'paid',
  'paid',
  'pending',
  'refunded',
  'failed',
]

function makeTransaction(index: number): Transaction {
  const first = FIRST[index % FIRST.length]
  const last = LAST[(index * 3) % LAST.length]
  const minutesAgo = index * 47 + (index % 5) * 9
  return {
    id: `TX-${String(10_000 + TOTAL - index)}`,
    customer: `${first} ${last}`,
    email: `${first}.${last}@example.com`.toLowerCase(),
    amount: ((index * 3731) % 48_000) / 100 + 9.5,
    status: STATUSES[(index * 5) % STATUSES.length],
    createdAt: new Date(
      Date.UTC(2026, 9, 6, 12) - minutesAgo * 60_000,
    ).toISOString(),
  }
}

// Demo only: the first request for this offset fails, so the retry state is
// visible. Reloading the page resets it.
const FAILING_CURSOR = 100
let hasFailed = false

/** Stands in for `GET /transactions?cursor=…` against a real API */
export async function fetchTransactions(cursor: number): Promise<Page> {
  await new Promise((resolve) => setTimeout(resolve, 700))

  if (cursor === FAILING_CURSOR && !hasFailed) {
    hasFailed = true
    throw new Error('Request failed')
  }

  const end = Math.min(cursor + PAGE_SIZE, TOTAL)
  const rows = Array.from({ length: end - cursor }, (_, i) =>
    makeTransaction(cursor + i),
  )
  return { rows, nextCursor: end < TOTAL ? end : null }
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'

export type InfinitePage<T> = {
  rows: T[]
  nextCursor: number | null
}

export type InfiniteStatus = 'idle' | 'loading' | 'error'

/**
 * Accumulates pages from a cursor-based fetcher. `fetchPage` must be a stable
 * reference (module-level or memoized), or the first page is requested again
 * on every render.
 */
export function useInfiniteRows<T>(
  fetchPage: (cursor: number) => Promise<InfinitePage<T>>,
) {
  const [rows, setRows] = useState<T[]>([])
  const [status, setStatus] = useState<InfiniteStatus>('idle')
  const [hasMore, setHasMore] = useState(true)
  const cursor = useRef<number | null>(0)
  // A ref, not state: two observer callbacks can fire before a re-render
  const inFlight = useRef(false)

  const loadMore = useCallback(async () => {
    if (inFlight.current || cursor.current === null) return
    inFlight.current = true
    setStatus('loading')
    try {
      const page = await fetchPage(cursor.current)
      cursor.current = page.nextCursor
      setRows((prev) => [...prev, ...page.rows])
      setHasMore(page.nextCursor !== null)
      setStatus('idle')
    } catch {
      setStatus('error')
    } finally {
      inFlight.current = false
    }
  }, [fetchPage])

  useEffect(() => {
    void loadMore()
  }, [loadMore])

  return { rows, status, hasMore, loadMore }
}

import type { ColumnDef } from '@tanstack/react-table'
import { Badge } from '#/components/ui/badge'
import { cn } from '#/lib/utils.ts'
import type { V9Features } from './features'
import type { Transaction, TransactionStatus } from './data'

const statusStyle: Record<TransactionStatus, string> = {
  paid: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  pending: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',
  refunded: 'bg-sky-500/10 text-sky-700 dark:text-sky-400',
  failed: 'bg-red-500/10 text-red-700 dark:text-red-400',
}

const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

const date = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeStyle: 'short',
  timeZone: 'UTC',
})

export const columns: ColumnDef<V9Features, Transaction>[] = [
  {
    accessorKey: 'id',
    header: 'Transaction',
    cell: ({ row }) => (
      <span className="font-mono text-xs">{row.original.id}</span>
    ),
  },
  {
    accessorKey: 'customer',
    header: 'Customer',
    cell: ({ row }) => (
      <div>
        <div className="font-medium">{row.original.customer}</div>
        <div className="text-xs text-muted-foreground">
          {row.original.email}
        </div>
      </div>
    ),
  },
  {
    accessorKey: 'status',
    header: 'Status',
    cell: ({ row }) => (
      <Badge
        variant="secondary"
        className={cn('capitalize', statusStyle[row.original.status])}
      >
        {row.original.status}
      </Badge>
    ),
  },
  {
    accessorKey: 'amount',
    header: () => <div className="text-right">Amount</div>,
    cell: ({ row }) => (
      <div className="text-right tabular-nums">
        {money.format(row.original.amount)}
      </div>
    ),
  },
  {
    accessorKey: 'createdAt',
    header: 'Date',
    cell: ({ row }) => (
      <span className="text-muted-foreground">
        {date.format(new Date(row.original.createdAt))}
      </span>
    ),
  },
]

'use client'

import { useEffect, useRef } from 'react'
import { flexRender, useTable } from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import { Skeleton } from '#/components/ui/skeleton'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { v9Features } from './features'
import { columns } from './columns'
import { useInfiniteRows } from './use-infinite-rows'
import type { InfinitePage } from './use-infinite-rows'
import type { Transaction } from './data'

const SKELETON_ROWS = 4

interface InfiniteScrollTableProps {
  fetchPage: (cursor: number) => Promise<InfinitePage<Transaction>>
  total: number
}

export function InfiniteScrollTable({
  fetchPage,
  total,
}: InfiniteScrollTableProps) {
  const { rows, status, hasMore, loadMore } = useInfiniteRows(fetchPage)
  const scrollRef = useRef<HTMLDivElement>(null)
  const sentinelRef = useRef<HTMLDivElement>(null)

  const table = useTable({
    features: v9Features,
    data: rows,
    columns,
    // v9Features registers pagination, which would cap the list at 10 rows
    manualPagination: true,
  })

  const canAutoLoad = hasMore && status === 'idle'

  // Depends on rows.length so a fresh observer is created after every page:
  // it reports the sentinel's current position straight away, which keeps
  // loading when a page was too short to push the sentinel out of view.
  useEffect(() => {
    const sentinel = sentinelRef.current
    if (!canAutoLoad || !sentinel) return

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) void loadMore()
      },
      { root: scrollRef.current, rootMargin: '0px 0px 160px 0px' },
    )
    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [canAutoLoad, loadMore, rows.length])

  return (
    <div>
      <div
        ref={scrollRef}
        className="max-h-96 overflow-auto rounded-md border [&_[data-slot=table-container]]:overflow-visible"
      >
        <Table>
          <TableHeader className="sticky top-0 z-10 bg-background shadow-[0_1px_0_var(--border)] [&_tr]:border-b-0">
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.map((row) => (
              <TableRow key={row.id}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))}
            {status === 'loading' &&
              Array.from({ length: SKELETON_ROWS }, (_, i) => (
                <TableRow key={`skeleton-${i}`} aria-hidden>
                  {columns.map((_column, j) => (
                    <TableCell key={j}>
                      <Skeleton className="h-4 w-full max-w-28" />
                    </TableCell>
                  ))}
                </TableRow>
              ))}
          </TableBody>
        </Table>
        <div ref={sentinelRef} className="h-px" aria-hidden />
        {status === 'error' && (
          <div
            role="alert"
            className="flex items-center justify-center gap-3 border-t p-3 text-sm"
          >
            <span className="text-muted-foreground">
              Couldn't load more transactions.
            </span>
            <Button size="sm" variant="outline" onClick={() => void loadMore()}>
              Retry
            </Button>
          </div>
        )}
      </div>
      <p
        className="mt-3 text-xs text-muted-foreground tabular-nums"
        aria-live="polite"
      >
        {hasMore
          ? `Showing ${rows.length} of ${total} — scroll for more`
          : `All ${total} transactions loaded`}
      </p>
    </div>
  )
}

import { InfiniteScrollTable } from './data-table'
import { TOTAL, fetchTransactions } from './data'

export function InfiniteScrollDemo() {
  return <InfiniteScrollTable fetchPage={fetchTransactions} total={TOTAL} />
}
